import SwiftUI
struct LucentPackageCounter: View {
  var onChange: (Double) -> Void
  @State private var count: Double = 0
  var body: some View {
    HStack {
      Button("−") { count -= 1; onChange(count) }
      Text("Native state: \(Int(count))")
      Button("+") { count += 1; onChange(count) }
    }
  }
}

kotlin.Counter.kt:
package {{androidPackage}}
import androidx.compose.runtime.*
import androidx.compose.foundation.layout.Row
import androidx.compose.material3.Button
import androidx.compose.material3.Text
@Composable
fun LucentPackageCounter(onChange: (Double) -> Unit) {
  var count by remember { mutableDoubleStateOf(0.0) }
  Row {
    Button(onClick = { count -= 1; onChange(count) }) { Text("−") }
    Text("Native state: ${count.toInt()}")
    Button(onClick = { count += 1; onChange(count) }) { Text("+") }
  }
}
